#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n;
    cin >> n;
    vector<int64_t> v(3 * n);
    for (auto& a : v) {
        cin >> a;
    }
    sort(v.rbegin(), v.rend());
    
    vector<int64_t> pref(3 * n + 1, 0);
    for (int i = 0; i < 3 * n; i++) {
        pref[i + 1] = pref[i] + v[i];
    }
    auto score = [&](int i, int pairs) -> int64_t {
        return 2 * pref[i] + pref[i + 2 * pairs] + 3 * pref[3 * n - 2 * i - pairs];
    };
    int64_t ans = 0;
    int pairs = n;
    for (int i  = 0; i <= n; i++) {
        pairs = min(pairs, n - i);
        while (pairs > 0 && score(i, pairs - 1) >= score(i, pairs)) {
            --pairs;
        }
        ans = max(ans, score(i, pairs));
    }
        // int low = 0, high = n - i;
        // while (low < high) {
        //     int mid = low + (high - low ) / 2;
        //     if (score(mid) < score(mid + 1)) {
        //         low = mid + 1;
        //     } else {
        //         high = mid;
        //     }
        // }
    cout << ans << endl;
    
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	cin >> t;
	while (t--) {
	    solve();
	    
	}
	return 0;

}
